/// The grapheme cluster class of one character.
pub(crate) fn grapheme_class_of(character: char) -> Grapheme {
    let code = character as u32;
    let after = GRAPHEMES.partition_point(|(first, _)| *first <= code);
    GRAPHEMES[after - 1].1
}

