/// The word break class of one character.
pub(crate) fn word_class_of(character: char) -> Word {
    let code = character as u32;
    let after = WORDS.partition_point(|(first, _)| *first <= code);
    WORDS[after - 1].1
}

/// Whether the tables are in order and leave no character out, which is
/// what the searches above take for granted.
#[cfg(test)]
pub(crate) fn in_order() -> bool {
    GRAPHEMES[0].0 == 0
        && GRAPHEMES.windows(2).all(|pair| pair[0].0 < pair[1].0)
        && WORDS[0].0 == 0
        && WORDS.windows(2).all(|pair| pair[0].0 < pair[1].0)
}
